            for k,v in inp.items():
                if isinstance(v, dict):
                    typ=v.get('type') or v.get('model_class')
                    print(prefix+k, typ, 'label=',v.get('label'), 'optional=',v.get('optional'), 'value=',v.get('value'))
                    if 'inputs' in v and len(prefix)<20:
