import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); h={'x-api-key':key}

def get(tid): return requests.get(url+'/api/tools/'+requests.utils.quote(tid,safe=''),headers=h,params={'io_details':'true'}).json()
def walk(inputs,p=''):
    for inp in inputs or []:
        name=inp.get('name'); typ=inp.get('type') or inp.get('model_class')
        print(f\"{p}{name}: {typ} label={inp.get('label')} value={inp.get('value')}\")
        if typ=='select' and name in ('ref_file','dbkey','genome','genome_version'):
            opts=inp.get('options') or []
            rel=[o for o in opts if any(s in (o[0]+o[1]).lower() for s in ['hg19','hg38','grch37','grch38','human'])]
            print('  relevant options', rel[:30], 'count',len(rel),'total',len(opts))
        for case in inp.get('cases') or []:
            print(f\"{p}  when {case.get('value')}\")
            walk(case.get('inputs') or [], p+'    ')
        if 'inputs' in inp and not inp.get('cases'):
            walk(inp.get('inputs'),p+'    ')

for tid in ['toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1','toolshed.g2.bx.psu.edu/repos/devteam/freebayes/freebayes/1.3.10+galaxy1','toolshed.g2.bx.psu.edu/repos/iuc/snpeff/snpEff/5.4+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/bcftools_mpileup/bcftools_mpileup/1.24+galaxy0']:
    print('\\n====',tid)
    walk(get(tid).get('inputs'))
