/bin/bash -lc "python - <<'PY'
import os,requests,json
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); h={'x-api-key':key}
ids=['toolshed.g2.bx.psu.edu/repos/iuc/snpsift/snpSift_filter/5.4.0c+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/snpsift/snpSift_extractFields/5.4.0c+galaxy0']
for tid in ids:
 obj=requests.get(url+'/api/tools/'+requests.utils.quote(tid,safe=''),headers=h,params={'io_details':'true'}).json()
 print('\\n====',tid,obj.get('name'))
 def rec(inputs,p=''):
  for inp in inputs or []:
   print(p+inp.get('name','?'),inp.get('type'), 'label=',inp.get('label'),'value=',inp.get('value'))
   if inp.get('type')=='conditional':
    print(' test',inp['test_param']['name'],'cases',[c.get('value') for c in inp['cases']])
    for c in inp['cases']: rec(c.get('inputs') or [],p+inp['name']+'|')
   elif inp.get('type') in ('repeat','section') or 'inputs' in inp:
    rec(inp.get('inputs') or [],p+inp.get('name','')+'|')
 rec(obj.get('inputs'))
PY"

